/**
 * Exércitos dos jogos de tabuleiro (pedido do dono, 11/10/2026): cada jogador escolhe o seu, e as
 * peças do xadrez (e o emblema das damas e o rei do hnefatafl) viram figuras de uma cultura: no deserto
 * o cavalo vira camelo, nos piratas o rei vira capitão, na fauna do Brasil o rei vira onça. Os desenhos
 * são silhuetas do game-icons.net (CC BY 3.0, autor por ícone, crédito na tela de créditos), baixadas
 * do repositório oficial em 11/10/2026; ficou só o caminho do desenho (sem o fundo preto), para pintar
 * com a cor do jogador. Gerado por um script a partir do repositório; `nome` é o que a figura faz de conta.
 */
import type { PieceType } from '@/services/xadrez-engine';

export interface PecaExercito {
  /** caminho SVG no quadro de 512×512 */
  d: string;
  /** o que a figura representa (ex. “camelo”) */
  nome: string;
  /** detalhes pintados por cima na cor do contorno (os olhos do cavalo, o corte do bispo) */
  detalhe?: string;
  icone: string;
  autor: string;
}

export interface Exercito {
  id: string;
  nome: string;
  /** o pacote da loja (Brasil, Japão…) */
  pacote: string;
  origem: string;
  preco: number;
  sobre: string;
  pecas: Record<PieceType, PecaExercito>;
}

/** As cores de um lado: o preenchimento e o contorno (sempre bem diferentes, para a figura ler em qualquer casa). */
export interface CoresLado {
  fundo: string;
  contorno: string;
  /** espessura do contorno, no quadro de 512 (padrão 44) */
  traco?: number;
}

/**
 * As cores de cada exército (pedido do dono: “o cacto é verde, as caveiras laranja”): um tom claro
 * para o jogador 1 e um escuro para o jogador 2, para dar para distinguir os dois mesmo quando os
 * dois escolhem o mesmo exército. O teste `exercitos-jogos.test.ts` confere o contraste.
 */
